/**
 * Gate 2 & Gate 3 Static Export Bundle Verification Script
 *
 * Inspects `out/` generated by `NEXT_STATIC_EXPORT=true npm run build` to verify:
 * 1. Required files (`index.html`, `404.html`, `_headers`, `manifest.json`, `icon.svg`, `_next/static/`) exist.
 * 2. `out/_headers` includes all 8 security headers expected by Cloudflare Pages.
 * 3. Public static HTML/JS/CSS/JSON artifacts contain ZERO accidental secrets, tokens, or telemetry hosts.
 */
import fs from 'node:fs';
import path from 'node:path';

const OUT_DIR = path.resolve(process.cwd(), 'out');

function fail(message) {
  console.error(`[verify-static-export] FAIL: ${message}`);
  process.exit(1);
}

if (!fs.existsSync(OUT_DIR)) {
  fail(`Directory not found: ${OUT_DIR}. Run NEXT_STATIC_EXPORT=true npm run build first.`);
}

const requiredPaths = [
  'index.html',
  '404.html',
  '_headers',
  'manifest.json',
  'icon.svg',
  '_next/static',
];

for (const rel of requiredPaths) {
  if (!fs.existsSync(path.join(OUT_DIR, rel))) {
    fail(`Missing required static artifact: out/${rel}`);
  }
}

const headersText = fs.readFileSync(path.join(OUT_DIR, '_headers'), 'utf8');
const requiredHeaders = [
  'Content-Security-Policy',
  'X-Frame-Options: DENY',
  'X-Content-Type-Options: nosniff',
  'Referrer-Policy: no-referrer',
  'Permissions-Policy',
  'Strict-Transport-Security',
  'Cross-Origin-Opener-Policy: same-origin',
  'Cross-Origin-Resource-Policy: same-origin',
];

for (const h of requiredHeaders) {
  if (!headersText.includes(h)) {
    fail(`Missing expected header directive in out/_headers: ${h}`);
  }
}

const secretPatterns = [
  { name: 'OpenAI-style key', regex: /\bsk-[A-Za-z0-9]{20,}\b/ },
  { name: 'AWS Access Key', regex: /\bAKIA[0-9A-Z]{16}\b/ },
  { name: 'Cloudflare API token pattern', regex: /\bCF_API_TOKEN\s*=\s*['"][^'"]+['"]/ },
  { name: 'Private key block', regex: /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/ },
  { name: 'Hardcoded Google Analytics ID', regex: /\bG-[A-Z0-9]{8,12}\b/ },
];

function walkFiles(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...walkFiles(full));
    } else if (/\.(html|js|css|json|svg|txt)$/i.test(entry.name)) {
      files.push(full);
    }
  }
  return files;
}

const scannedFiles = walkFiles(OUT_DIR);
for (const file of scannedFiles) {
  const content = fs.readFileSync(file, 'utf8');
  for (const { name, regex } of secretPatterns) {
    if (regex.test(content)) {
      fail(`Potential secret (${name}) found in static bundle: ${path.relative(OUT_DIR, file)}`);
    }
  }
}

const indexHtml = fs.readFileSync(path.join(OUT_DIR, 'index.html'), 'utf8');
if (!indexHtml.includes('HearthShift AI')) {
  fail('out/index.html missing expected application title.');
}

console.log(
  `[verify-static-export] PASS: Verified ${scannedFiles.length} static assets in out/ (all required artifacts, 8 security headers, 0 secret patterns).`
);
